export type PopupAction = "ALLOW" | "BLOCK" | "QUARANTINE_PROMPT";

export type PopupCategory =
  | "AUTH_OAUTH"
  | "PAYMENT_GATEWAY"
  | "AD_INTRUSIVE"
  | "CLICKJACKING"
  | "NEWSLETTER_GATE"
  | "BENIGN_UI"
  | "AMBIGUOUS_UNKNOWN";

export interface PopupDecision {
  action: PopupAction;
  riskScore: number;
  category: PopupCategory;
  confidence: number;
  reasoning: string;
  modelId: string;
  consumedAt: string;
}

const CONSUMED_AT_LOCATION = "src/core/engine/decision-schema.ts:parsePopupDecision";

/**
 * Parses raw text or JSON generated by an open-weight model into a verified PopupDecision.
 * If generation is malformed, conservatively falls back to QUARANTINE_PROMPT.
 */
export function parsePopupDecision(rawResponse: string): PopupDecision {
  try {
    // 1. Strip markdown code fences if model returned ```json ... ```
    let cleaned = rawResponse.trim();
    if (cleaned.startsWith("```")) {
      cleaned = cleaned.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "");
    }

    const parsed = JSON.parse(cleaned);

    const validActions: PopupAction[] = ["ALLOW", "BLOCK", "QUARANTINE_PROMPT"];
    const action: PopupAction = validActions.includes(parsed.action)
      ? parsed.action
      : "QUARANTINE_PROMPT";

    const riskScore =
      typeof parsed.riskScore === "number" && !isNaN(parsed.riskScore)
        ? Math.max(0, Math.min(1, parsed.riskScore))
        : 0.5;

    const confidence =
      typeof parsed.confidence === "number" && !isNaN(parsed.confidence)
        ? Math.max(0, Math.min(1, parsed.confidence))
        : 0.5;

    return {
      action,
      riskScore,
      category: parsed.category || "AMBIGUOUS_UNKNOWN",
      confidence,
      reasoning: String(parsed.reasoning || "No reasoning provided"),
      modelId: String(parsed.modelId || "unknown-model"),
      consumedAt: CONSUMED_AT_LOCATION,
    };
  } catch (_err) {
    // Graceful fallback for non-JSON or corrupted model responses
    return {
      action: "QUARANTINE_PROMPT",
      riskScore: 0.5,
      category: "AMBIGUOUS_UNKNOWN",
      confidence: 0.0,
      reasoning: "Fallback triggered: raw model output could not be parsed as valid JSON decision",
      modelId: "fallback",
      consumedAt: CONSUMED_AT_LOCATION,
    };
  }
}
